#workspace-update-dialog{inset:0;margin:auto;width:min(680px,calc(100vw - 32px));max-width:calc(100vw - 32px);height:auto;max-height:85vh;border:1px solid var(--line);border-radius:14px;padding:28px;overflow-y:auto}#workspace-update-dialog h1{font-size:30px;margin:0 0 12px}#workspace-update-dialog h2{font-size:20px}.workspace-release+.workspace-release{border-top:1px solid var(--line);padding-top:24px;margin-top:24px}.workspace-release-list{padding-left:20px}.workspace-release-list li{padding-left:4px;margin:16px 0}.workspace-release-list p{margin:5px 0 0;line-height:1.6;font-size:13px}.workspace-release h2{font-size:22px}.workspace-release .eyebrow{margin-top:16px}#workspace-update-dialog .modal-form-actions{position:static;display:flex;justify-content:flex-end;flex-wrap:wrap;gap:10px;border-top:1px solid var(--line);margin-top:24px;padding-top:18px}

.journey-section-actions{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:16px}

.configuration-metric-actions{display:flex;flex-direction:column;align-items:flex-start;gap:12px;margin-top:12px}.configuration-metric-actions .client-blocker-link{margin-top:0;white-space:normal}
